// Contra un Postgres real en memoria, con el esquema de las migraciones del escritorio.
import { PGlite } from '@electric-sql/pglite';
import { beforeEach, describe, expect, it } from 'vitest';
import type { NewGame } from './gameInput';
import { DuplicateBarcodeError, gameRepository } from './gameRepository';

const SCHEMA = `
  CREATE TABLE "Games" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Barcode" text,
    "Title" text NOT NULL,
    "Platform" text NOT NULL,
    "Publisher" text NOT NULL,
    "Genre" text NOT NULL,
    "Tags" text NOT NULL,
    "Year" integer,
    "CoverUrl" text NOT NULL,
    "CoverData" bytea,
    "Notes" text NOT NULL,
    "Rating" integer NOT NULL,
    "Played" boolean NOT NULL,
    "IsWishlist" boolean NOT NULL,
    "AddedDate" timestamp without time zone NOT NULL,
    "DeletedDate" timestamp without time zone
  );
  CREATE UNIQUE INDEX "IX_Games_Barcode" ON "Games" ("Barcode") WHERE "DeletedDate" IS NULL;
`;

const newGame: NewGame = {
  barcode: '045496590048',
  title: 'Mario Kart',
  platform: 'Switch',
  genre: 'Carreras',
  publisher: 'Nintendo',
  tags: 'favorito',
  year: 2017,
  coverUrl: 'https://example.com/a.jpg',
  notes: '',
  rating: 4,
  played: false,
  isWishlist: false,
};

const COVER = new Uint8Array([0xff, 0xd8, 0x00, 0x7f, 0x80, 0xff]);

describe('gameRepository', () => {
  let db: PGlite;
  let repository: ReturnType<typeof gameRepository>;

  beforeEach(async () => {
    db = new PGlite();
    await db.exec(SCHEMA);
    repository = gameRepository(async (text, params) => (await db.query(text, params)).rows as Record<string, unknown>[]);
  });

  it('el nombre de la colección empieza vacío y se puede cambiar', async () => {
    expect(await repository.getCollectionName()).toBe('');

    await repository.setCollectionName('Mi estantería');
    await repository.setCollectionName('La colección de casa');

    expect(await repository.getCollectionName()).toBe('La colección de casa');
  });

  it('comprueba que la base de datos tiene colección', async () => {
    await expect(repository.assertCollectionExists()).resolves.toBeUndefined();

    await db.exec('DROP TABLE "Games"');
    await expect(repository.assertCollectionExists()).rejects.toThrow();
  });

  it('crea un juego con todos sus datos y su portada', async () => {
    const game = await repository.create(newGame, COVER, 'Europe/Madrid');

    expect(game).toMatchObject({ ...newGame, coverSize: COVER.length });
    expect(game.addedDate).toMatch(/^\d{4}-\d{2}-\d{2} /);
    expect(await repository.getCover(game.id)).toEqual(COVER);
    expect(await repository.getAll()).toHaveLength(1);
  });

  it('guarda la fecha en la hora local del usuario', async () => {
    const madrid = await repository.create({ ...newGame, barcode: null }, null, 'Asia/Tokyo');
    const utc = await repository.create({ ...newGame, barcode: null }, null, 'UTC');
    const hours = (Date.parse(madrid.addedDate) - Date.parse(utc.addedDate)) / 3_600_000;
    expect(Math.round(hours)).toBe(9);
  });

  it('crea sin portada ni código', async () => {
    const game = await repository.create({ ...newGame, barcode: null }, null, 'UTC');
    expect(game.coverSize).toBe(0);
    expect(await repository.getCover(game.id)).toBeNull();
  });

  it('rechaza el mismo código, también en su otra forma', async () => {
    await repository.create(newGame, null, 'UTC');
    await expect(repository.create(newGame, null, 'UTC')).rejects.toThrow(DuplicateBarcodeError);
    await expect(repository.create({ ...newGame, barcode: '0045496590048' }, null, 'UTC')).rejects.toThrow(
      DuplicateBarcodeError,
    );
  });

  it('permite repetir el código de un juego que está en la papelera', async () => {
    const game = await repository.create(newGame, null, 'UTC');
    await repository.moveToTrash(game.id, 'UTC');
    await expect(repository.create(newGame, null, 'UTC')).resolves.toBeDefined();
  });

  it('al actualizar solo cambia lo recibido y conserva la portada', async () => {
    const game = await repository.create(newGame, COVER, 'UTC');

    const updated = await repository.update(game.id, { played: true, notes: 'Terminado' });

    expect(updated).toMatchObject({ ...newGame, played: true, notes: 'Terminado', coverSize: COVER.length });
    expect(updated?.addedDate).toBe(game.addedDate);
    expect(await repository.getCover(game.id)).toEqual(COVER);
  });

  it('cambia la portada solo si se le pide', async () => {
    const game = await repository.create(newGame, COVER, 'UTC');
    const replacement = new Uint8Array([1, 2, 3]);

    await repository.update(game.id, { coverUrl: 'https://example.com/b.jpg' }, replacement);
    expect(await repository.getCover(game.id)).toEqual(replacement);

    await repository.update(game.id, { coverUrl: 'https://example.com/c.jpg' }, null);
    expect(await repository.getCover(game.id)).toBeNull();
  });

  it('el año se puede dejar vacío', async () => {
    const game = await repository.create(newGame, null, 'UTC');
    expect((await repository.update(game.id, { year: null }))?.year).toBeNull();
  });

  it('no falla si no hay nada que cambiar', async () => {
    const game = await repository.create(newGame, null, 'UTC');
    await expect(repository.update(game.id, {})).resolves.toMatchObject({ title: newGame.title });
  });

  it('avisa si el código ya lo usa otro juego al actualizar', async () => {
    await repository.create(newGame, null, 'UTC');
    const other = await repository.create({ ...newGame, barcode: null }, null, 'UTC');
    await expect(repository.update(other.id, { barcode: newGame.barcode })).rejects.toThrow(DuplicateBarcodeError);
  });

  it('elimina varios juegos a la vez y no toca el resto', async () => {
    const first = await repository.create({ ...newGame, barcode: null, title: 'Primero' }, null, 'UTC');
    const second = await repository.create({ ...newGame, barcode: null, title: 'Segundo' }, null, 'UTC');
    await repository.create({ ...newGame, barcode: null, title: 'Se queda' }, null, 'UTC');

    const moved = await repository.moveManyToTrash([first.id, second.id], 'UTC');

    expect(moved.toSorted()).toEqual([first.id, second.id].toSorted());
    expect((await repository.getAll()).map((game) => game.title)).toEqual(['Se queda']);
    expect(await repository.getTrash()).toHaveLength(2);
  });

  it('al eliminar varios ignora los que no existen o ya están en la papelera', async () => {
    const trashed = await repository.create({ ...newGame, barcode: null }, null, 'UTC');
    const active = await repository.create({ ...newGame, barcode: null }, null, 'UTC');
    await repository.moveToTrash(trashed.id, 'UTC');

    expect(await repository.moveManyToTrash([trashed.id, active.id, 9999], 'UTC')).toEqual([active.id]);
  });

  it('la papelera lista lo eliminado, lo más reciente primero', async () => {
    const first = await repository.create({ ...newGame, barcode: null, title: 'Primero' }, null, 'UTC');
    const second = await repository.create({ ...newGame, barcode: null, title: 'Segundo' }, null, 'UTC');
    await repository.create({ ...newGame, barcode: null, title: 'Activo' }, null, 'UTC');
    await repository.moveToTrash(first.id, 'UTC');
    await repository.moveToTrash(second.id, 'Asia/Tokyo');

    const trash = await repository.getTrash();

    expect(trash.map((game) => game.title)).toEqual(['Segundo', 'Primero']);
    expect(trash[0].deletedDate).toMatch(/^\d{4}-\d{2}-\d{2} /);
  });

  it('restaurar devuelve el juego a la colección con su portada', async () => {
    const game = await repository.create(newGame, COVER, 'UTC');
    await repository.moveToTrash(game.id, 'UTC');

    const restored = await repository.restore(game.id);

    expect(restored).toMatchObject({ title: newGame.title, coverSize: COVER.length });
    expect(await repository.getTrash()).toEqual([]);
    expect(await repository.getAll()).toHaveLength(1);
  });

  it('no restaura si otro juego ocupa ya su código', async () => {
    const game = await repository.create(newGame, null, 'UTC');
    await repository.moveToTrash(game.id, 'UTC');
    await repository.create(newGame, null, 'UTC');

    await expect(repository.restore(game.id)).rejects.toThrow(DuplicateBarcodeError);
    expect(await repository.getTrash()).toHaveLength(1);
  });

  it('el borrado definitivo solo afecta a lo que está en la papelera', async () => {
    const active = await repository.create(newGame, null, 'UTC');
    expect(await repository.deleteForever(active.id)).toBe(false);
    expect(await repository.getAll()).toHaveLength(1);

    await repository.moveToTrash(active.id, 'UTC');
    expect(await repository.deleteForever(active.id)).toBe(true);
    expect(await repository.getTrash()).toEqual([]);
  });

  it('restaurar ignora juegos que no están en la papelera', async () => {
    const game = await repository.create(newGame, null, 'UTC');
    expect(await repository.restore(game.id)).toBeNull();
  });

  it('no toca juegos que no existen o están en la papelera', async () => {
    const game = await repository.create(newGame, null, 'UTC');
    await repository.moveToTrash(game.id, 'UTC');

    expect(await repository.update(game.id, { title: 'Otro' })).toBeNull();
    expect(await repository.update(9999, { title: 'Otro' })).toBeNull();
    expect(await repository.moveToTrash(game.id, 'UTC')).toBe(false);
    expect(await repository.getAll()).toEqual([]);
  });
});
